def investigate(context, acquire):
    history = acquire("history")

    def simulate(actions, put_mode, trigger, channel_mode):
        committed = {}
        conns = {'main': {'txn': False, 'pending': {}}, 'other': {'txn': False, 'pending': {}}}
        total = {'main': 0, 'other': 0}

        def get_view(conn):
            view = dict(committed)
            for k, v in conns[conn]['pending'].items():
                if v is None:
                    view.pop(k, None)
                else:
                    view[k] = v
            return view

        for act in actions:
            op = act.get('op')
            conn = act.get('connection', 'main')
            if op == 'begin':
                conns[conn]['txn'] = True
                conns[conn]['pending'] = {}
            elif op == 'commit':
                for k, v in conns[conn]['pending'].items():
                    if v is None:
                        committed.pop(k, None)
                    else:
                        committed[k] = v
                conns[conn]['txn'] = False
                conns[conn]['pending'] = {}
            elif op == 'rollback':
                conns[conn]['txn'] = False
                conns[conn]['pending'] = {}
            elif op == 'put':
                key = act['key']
                val = act['value']
                view = get_view(conn)
                changed = 0
                if put_mode == 'ignore':
                    if key not in view:
                        changed = 1
                        if conns[conn]['txn']:
                            conns[conn]['pending'][key] = val
                        else:
                            committed[key] = val
                elif put_mode == 'replace':
                    if key in view:
                        changed = 2
                    else:
                        changed = 1
                    if conns[conn]['txn']:
                        conns[conn]['pending'][key] = val
                    else:
                        committed[key] = val
                else:
                    if key in view:
                        changed = 1
                    else:
                        changed = 1
                    if conns[conn]['txn']:
                        conns[conn]['pending'][key] = val
                    else:
                        committed[key] = val
                if changed:
                    total[conn] += changed
                    if trigger:
                        total[conn] += 1
            elif op == 'update':
                key = act['key']
                val = act['value']
                view = get_view(conn)
                if key in view:
                    if conns[conn]['txn']:
                        conns[conn]['pending'][key] = val
                    else:
                        committed[key] = val
                    total[conn] += 1
            elif op == 'delete':
                key = act['key']
                view = get_view(conn)
                if key in view:
                    if conns[conn]['txn']:
                        conns[conn]['pending'][key] = None
                    else:
                        committed.pop(key, None)
                    total[conn] += 1

        if channel_mode == 'main':
            ch = total['main']
        else:
            ch = total['main'] + total['other']
        return ch, len(committed), sum(committed.values())

    def consistent(put_mode, trigger, channel_mode):
        for rec in history:
            acts = rec.get('actions', [])
            obs = rec.get('observed', {})
            ch, cnt, sm = simulate(acts, put_mode, trigger, channel_mode)
            if ch != obs.get('channel'):
                return False
            if cnt != obs.get('committed_count'):
                return False
            if sm != obs.get('committed_sum'):
                return False
        return True

    candidates = []
    for put_mode in ('ignore', 'replace', 'upsert'):
        for trigger in (False, True):
            for channel_mode in ('main', 'both'):
                if consistent(put_mode, trigger, channel_mode):
                    candidates.append((put_mode, trigger, channel_mode))

    actions = context.get('actions', [])
    goal = context.get('goal')

    if not candidates:
        return {'value': None, 'unresolved': True}

    results = []
    for put_mode, trigger, channel_mode in candidates:
        ch, cnt, sm = simulate(actions, put_mode, trigger, channel_mode)
        if goal == 'channel':
            results.append(ch)
        elif goal == 'committed_count':
            results.append(cnt)
        elif goal == 'committed_sum':
            results.append(sm)
        else:
            return {'value': None, 'unresolved': True}

    first = results[0]
    for r in results:
        if r != first:
            return {'value': None, 'unresolved': True}
    return {'value': first, 'unresolved': False}

